const { PDFDocument } = require('pdf-lib');
const fontkit = require('@pdf-lib/fontkit');
const fs = require('fs');

(async () => {
  const doc = await PDFDocument.create();
  doc.registerFontkit(fontkit);
  const fontBytes = fs.readFileSync('/usr/share/fonts/workspacex/NotoSansSC-Common.otf');
  const font = await doc.embedFont(fontBytes);

  const pageW = 595, pageH = 842;
  const marginL = 50, marginR = 50;
  const contentW = pageW - marginL - marginR;

  // Helper: draw wrapped Chinese text, returns next y
  function drawText(page, text, x, y, size, opts = {}) {
    const maxChars = Math.floor(contentW / size);
    let line = '';
    let cy = y;
    for (let i = 0; i < text.length; i++) {
      line += text[i];
      if (line.length >= maxChars || text[i] === '\n') {
        const drawLine = line.replace(/\n/g, '');
        if (drawLine.length > 0) {
          page.drawText(drawLine, { x, y: cy, size, font, ...opts });
        }
        cy -= size * 1.5;
        line = '';
      }
    }
    if (line.length > 0) {
      page.drawText(line, { x, y: cy, size, font, ...opts });
      cy -= size * 1.5;
    }
    return cy;
  }

  // --- Page 1 ---
  let page = doc.addPage([pageW, pageH]);
  let y = 780;

  // Title
  page.drawText('AI 助手能力总览', { x: marginL, y, size: 28, font });
  y -= 50;

  // Subtitle
  y = drawText(page, '以下是我能够为您完成的主要工作类别与具体能力。', marginL, y, 13);
  y -= 15;

  // Section helper
  function section(title, items) {
    if (y < 120) {
      page = doc.addPage([pageW, pageH]);
      y = 780;
    }
    page.drawText('■ ' + title, { x: marginL, y, size: 16, font });
    y -= 28;
    for (const item of items) {
      if (y < 60) {
        page = doc.addPage([pageW, pageH]);
        y = 780;
      }
      y = drawText(page, '• ' + item, marginL + 10, y, 11);
      y -= 4;
    }
    y -= 12;
  }

  section('文档创建与编辑', [
    '生成 Word (.docx)、Excel (.xlsx)、PowerPoint (.pptx)、PDF 文件',
    '对已有 Office 文档进行有限的文本替换与单元格修改',
    '填写 PDF 标准表单域（AcroForm 文本框与复选框）',
  ]);

  section('数据分析与可视化', [
    '读取 CSV / XLSX / JSON 数据，执行统计分析与质量检查',
    '生成柱状图、折线图、饼图等静态图表，支持中文标签',
    '输出可复现的分析脚本与数据质量说明',
  ]);

  section('会议与沟通', [
    '将会议转录整理为纪要：决策、行动项与证据定位',
    '准备会议背景材料、议程与预读文档',
    '撰写内部公告、领导更新、FAQ、3P 周报等沟通草稿',
    '生成项目状态报告与里程碑简报',
  ]);

  section('研究与知识管理', [
    '联网检索公开资料，形成带引用的研究报告',
    '基于组织内部资料回答知识问题并标注出处',
    '综合多场访谈记录，提炼主题、引文与反例',
    '规划用户研究方案、招募条件与中立访谈提纲',
  ]);

  // --- Page 2 if needed ---
  if (y < 120) {
    page = doc.addPage([pageW, pageH]);
    y = 780;
  }

  section('创意与视觉内容', [
    '制作海报、配图等静态视觉作品的构图与文案',
    '生成 MAAU 画布（最小智能体可执行单元）',
    '创建 Mermaid 图表与可编辑画布',
    '构建自包含交互式网页产物并通过浏览器验收',
  ]);

  section('音视频处理', [
    '将音频转录为可审阅文本，保留时间范围与识别局限',
    '读取图片、PDF 等多模态内容并提取信息',
  ]);

  section('系统与工具', [
    '在沙箱中执行 Shell 命令与脚本',
    '文件读写、搜索、目录浏览等文件系统操作',
    '将工作流封装为可复用技能草稿包',
    '发布生成的文件供下载',
  ]);

  y -= 20;
  if (y < 80) {
    page = doc.addPage([pageW, pageH]);
    y = 780;
  }
  page.drawLine({ start: { x: marginL, y }, end: { x: pageW - marginR, y }, thickness: 1, color: { r: 0.6, g: 0.6, b: 0.6 } });
  y -= 25;
  y = drawText(page, '以上能力均可组合使用。如有具体需求，请直接描述，我会选择最合适的方式为您完成。', marginL, y, 11);

  const bytes = await doc.save();
  fs.writeFileSync('/workspace/ai-capabilities-summary.pdf', bytes);
  console.log('PDF generated successfully.');
})().catch((e) => { console.error(e.stack); process.exit(1); });
